function FileButton({path, label = "查看证据"}: {path: string; label?: string}) {
  const dispatch = useCanvasAction();
  return <Button variant="ghost" onClick={() => dispatch({type:"openFile", path:ROOT + path})}>{label}</Button>;
}

function Evidence({label, children}: {label: string; children: string}) {
  return <Stack gap={3}><Text size="small" tone="tertiary">{label}</Text><Text>{children}</Text></Stack>;
}

