function GrowthPanel() {
  const [storageHp, setStorageHp] = useState(100);
  const loot = lootData.filter(row => row.storageHp === storageHp);
  return <Stack gap={22}>
    <Stack gap={8}>
      <H2>6 条永久成长，17 次购买，334 薪柴</H2>
      <Text tone="secondary">另加厚 3 档 / 64 薪柴：全部购买共 20 次 / 398 薪柴。修复、武器消耗与携带物不计入，不能据此换算毕业时间。</Text>
      <Table headers={["成长条目", "等级上限", "逐级价格（薪柴）", "封顶总价", "当前实际收益"]} rows={upgradeData.map(u => [u.name, u.maxLevel, u.costs.join(" / "), u.totalCost, u.effect])} columnAlign={["left","right","left","right","left"]} />
      <Text size="small" tone="tertiary">来源：data/upgrades.csv、实际消费链与 growth/analysis.json；2026-09-20。价格为每级单价，封顶总价为各级相加。</Text>
      <CollapsibleSection title="展开 20 次购买的逐级成本与累计成本">
        <Table headers={["条目", "目标等级", "本级价格（薪柴）", "该条累计（薪柴）"]} rows={upgradeData.flatMap(u=>u.costs.map((cost,i)=>[u.name,i+1,cost,u.costs.slice(0,i+1).reduce((a,b)=>a+b,0)]))} columnAlign={["left","right","right","right"]} />
      </CollapsibleSection>
    </Stack>
    <Divider />
    <Stack gap={8}>
      <H3>亲和收益算例：一次完整搜撤可带回的薪柴</H3>
      <Row wrap gap={8}><Text size="small" tone="secondary">储藏 HP（点）</Text>{[0,70,100].map(hp=><span key={hp}><Pill active={hp===storageHp} onClick={()=>setStorageHp(hp)}>{hp}</Pill></span>)}</Row>
      <Text size="small" tone="secondary">纵轴：整图回收薪柴（个） · 横轴：亲和等级（级）</Text>
      <BarChart categories={loot.map(x=>`${x.affinity} 级`)} series={[{name:"整图回收薪柴", data:loot.map(x=>x.fullMapYield),tone:"neutral"}]} height={200} valueSuffix=" 薪柴" showValues />
      <Text>一级价格 8；在此条件下，比 0 级多带回 {loot[1].fullMapYield-loot[0].fullMapYield} 薪柴。下一次相同完整搜撤的增量已覆盖价格，值得优先调查其购买顺序优势。</Text>
      <Text size="small" tone="tertiary">来源：growth/analysis.json · 2026-09-20 函数算例。固定 8 堆（3 安全、3 争夺、2 深层），全部找到且成功带回，无其他修正；不代表自然玩家平均收入。</Text>
    </Stack>
    <Divider />
    <Stack gap={6}><H3>结构、价值与可靠性</H3>{growthFindings.map(f=><div key={f.id}><CollapsibleSection title={`${f.id} · ${f.title}`} trailing={<Pill size="sm">{f.rank}</Pill>}><Stack gap={10}><Evidence label="核实事实">{f.fact}</Evidence><Evidence label="裁决与限度">{f.judgment}</Evidence><Evidence label="下一步验证">{f.next}</Evidence><FileButton path={ART+f.evidence} /></Stack></CollapsibleSection></div>)}</Stack>
  </Stack>;
}

